func automationMetricsJSON(metrics models.AutomationMetrics) string {
	value, _ := json.Marshal(metrics)
	return string(value)
}
func automationReplayJSON(frames []models.AutomationReplayFrame) string {
	value, _ := json.Marshal(frames)
	return string(value)
}
func automationHealthBadgeClass(state models.AutomationHealthState) string {
	switch state {
	case models.AutomationHealthHealthy:
		return "badge badge-success badge-outline"
	case models.AutomationHealthDegraded:
		return "badge badge-warning badge-outline"
	case models.AutomationHealthUnhealthy:
		return "badge badge-error badge-outline"
	}
	return "badge badge-ghost"
}
func automationInvocationHistoryTime(invocation models.AutomationInvocation) time.Time {
	if invocation.ScheduledFor != nil {
		return *invocation.ScheduledFor
	}
	if invocation.StartedAt != nil {
		return *invocation.StartedAt
	}
	return invocation.CreatedAt
}
func automationInvocationLabel(invocation models.AutomationInvocation) string {
	if invocation.ScheduledFor != nil {
		return "Scheduled occurrence"
	}
	return "Invocation " + automationShortID(invocation.ID)
}
func automationWorkItemLabel(item models.AutomationWorkItem) string {
	if strings.TrimSpace(item.Title) != "" {
		return item.Title
	}
	return item.Kind + " " + automationShortID(item.ID)
}
func automationShortID(value string) string {
	if len(value) <= 8 {
		return value
	}
	return value[:8]
}
func automationNodeName(nodes []models.AutomationNode, nodeID string) string {
	for _, node := range nodes {
		if node.ID == nodeID {
			return node.Name
		}
	}
	return "Unknown node"
}
func automationInvocationNodeClass(history models.AutomationInvocationHistory, nodeID string) string {
	for _, touchedNodeID := range history.TouchedNodeIDs {
		if touchedNodeID == nodeID {
			return "fill-primary/15 stroke-primary"
		}
	}
	return "fill-base-200 stroke-base-content/25"
}

func automationCardSearchText(card models.AutomationCard) string {
	return strings.Join([]string{card.Automation.Name, card.Automation.Description, card.Version.AdapterKey, string(card.Automation.LifecycleState), string(card.Automation.HealthState)}, " ")
}
func automationTime(value *time.Time, empty string) string {
	if value == nil {
		return empty
	}
	return value.Local().Format("Jan 2, 3:04 PM")
}
func automationGraphWidth(nodes []models.AutomationNode) int {
	max := 900.0
	for _, n := range nodes {
		if n.PositionX+180 > max {
			max = n.PositionX + 180
		}
	}
	return int(max)
}
func automationGraphHeight(nodes []models.AutomationNode) int {
	max := 420.0
	for _, n := range nodes {
		if n.PositionY+130 > max {
			max = n.PositionY + 130
		}
	}
	return int(max)
}
func automationEdgeNodes(nodes []models.AutomationNode, edge models.AutomationEdge) (models.AutomationNode, models.AutomationNode, bool) {
	var source, target models.AutomationNode
	var foundSource, foundTarget bool
	for _, n := range nodes {
		if n.ID == edge.SourceNodeID {
			source, foundSource = n, true
		}
		if n.ID == edge.TargetNodeID {
			target, foundTarget = n, true
		}
	}
	return source, target, foundSource && foundTarget
}
func automationNodeLabel(value string, limit int) string {
	r := []rune(value)
	if len(r) <= limit {
		return value
	}
	return string(r[:limit-1]) + "…"
}
func resourcesForAutomationNode(resources []models.AutomationResourceSummary, nodeID string) []models.AutomationResourceSummary {
	var out []models.AutomationResourceSummary
	for _, resource := range resources {
		if resource.NodeID == nodeID {
			out = append(out, resource)
		}
	}
	return out
}

